#include "cvr_terrain_context.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int main(int argc,char**argv){if(argc!=2&&argc!=5)return 20;FILE*f=fopen(argv[1],"rb");if(!f)return 20;if(fseek(f,0,2)){fclose(f);return 20;}long n=ftell(f);rewind(f);if(n<=0||n>64*1024*1024){fclose(f);return 20;}auto*p=(uint8_t*)malloc(n);if(!p){fclose(f);return 20;}const bool ok=fread(p,1,n,f)==(size_t)n;fclose(f);alpha::OriginalWorld w;const bool loaded=ok&&w.load(p,n,1)==alpha::WorldLoadError::ok;free(p);if(!loaded)return 20;{const auto&m=w.game().map.info;bool checked=false;for(unsigned y=0;!checked&&y<m.height;++y)for(unsigned x=y&1;!checked&&x<m.width;x+=2){alpha::CvrTerrainCorners c{};if(!alpha::cvr_terrain_corners(w,x,y,1,c))continue;const void* allocations[]={&w,w.original_bytes(),w.tile(0),w.vehicle(0),w.base(0),w.prototype(0),w.faction(0),w.faction_definition(0)};for(const void*p:allocations)if(p){unsigned char before[sizeof(c)];memcpy(before,p,sizeof(c));auto&out=*reinterpret_cast<alpha::CvrTerrainCorners*>(const_cast<void*>(p));if(alpha::cvr_terrain_corners(w,x,y,1,out)||memcmp(before,p,sizeof(c)))return 20;}alpha::CvrTerrainCorners unchanged;memset(&unchanged,0xa5,sizeof(unchanged));unsigned char before[sizeof(unchanged)];memcpy(before,&unchanged,sizeof(unchanged));if(alpha::cvr_terrain_corners(w,-1,0,1,unchanged)||memcmp(before,&unchanged,sizeof(unchanged)))return 20;checked=true;}}if(argc==5){alpha::CvrTerrainCorners c{};const bool ok=alpha::cvr_terrain_corners(w,atoi(argv[2]),atoi(argv[3]),(unsigned)atoi(argv[4]),c);printf("%u",ok?1u:0u);for(uint8_t v:c.relative)printf(" %u",(unsigned)v);for(int v:c.height)printf(" %d",v);puts("");return 0;}unsigned cases=0;const auto&m=w.game().map.info;for(unsigned y=0;y<m.height;++y)for(unsigned x=y&1;x<m.width;x+=2){if((w.tile((y*m.width+x)/2)->climate>>5)<3)continue;alpha::CvrTerrainCorners c{};if(!alpha::cvr_terrain_corners(w,x,y,1,c))return 20;unsigned words[10]={x,y,c.relative[0],c.relative[1],c.relative[2],c.relative[3],(unsigned)c.height[0],(unsigned)c.height[1],(unsigned)c.height[2],(unsigned)c.height[3]};for(unsigned v:words)for(unsigned k=0;k<4;++k)putchar((int)((v>>(8*k))&255));++cases;}fprintf(stderr,"TERRAIN %u ordinary land corner records\n",cases);return 0;}
